// Using startsWith for prefix matching to catch --output-file, --output=..., etc.
// For short flags, -O is listed explicitly; compound short flags (-op) are blocked
// because a letter after -o is a different flag entirely in git's parser.
const GIT_READ_WRITE_FLAGS: ReadonlySet<string> = new Set(['--output', '--upload-pack', '--receive-pack', '-o', '-O']);
// In routeGit, change the check to:
