// NOTE: This regex does not handle escaped quotes within quoted strings
// (e.g., "he said \"hi\"") or backslash-newline continuations. These
// edge cases are low-probability in practice but could cause mis-tokenization.
const rawTokens = trimmed.match(/[^\s"']+|"(?:[^"\\]|\\.)*"|'[^']*'/g) ?? [];
